def runtime_health_path() -> Path:
    """Prefer the live top-level workspace, fall back to legacy nested paths."""
    primary = WORKSPACE_DIR / "health.json"
    if primary.exists():
        return primary
    return BASE_DIR / "minime" / "workspace" / "health.json"


def runtime_workspace_path(name: str) -> Path:
    """Resolve files that may exist in either the live or legacy workspace."""
    primary = WORKSPACE_DIR / name
    if primary.exists():
        return primary
    return BASE_DIR / "minime" / "workspace" / name


def _load_sensory_source_state() -> Dict[str, Any]:
    try:
        data = json.loads(SENSORY_SOURCE_STATE_PATH.read_text())
    except Exception:
        return {}
    updated_at_ms = int(data.get("updated_at_ms", 0) or 0)
    if updated_at_ms <= 0:
        return {}
    age_ms = int(time.time() * 1000) - updated_at_ms
    if age_ms > SENSORY_SOURCE_MAX_AGE_MS:
        return {}
    return data


def _current_modality_source(modality: str) -> str:
    data = _load_sensory_source_state()
    return str(data.get(modality, {}).get("source", "physical"))


def _configured_look_source() -> str:
    return os.environ.get("LOOK_SOURCE", "active").strip().lower()


def _effective_look_source() -> str:
    configured = _configured_look_source()
    if configured in ("physical", "host"):
        return configured
    return _current_modality_source("video")


def _look_target_description(source: Optional[str] = None) -> str:
    source = source or _effective_look_source()
    if source == "host":
        return "the host machine's internal state"
    return "the physical world"


def _audio_target_description(source: Optional[str] = None) -> str:
    source = source or _current_modality_source("audio")
    if source == "host":
        return "a synthetic sonification of the host machine"
    return "a microphone in the room around your hardware"


def _sensory_control_dir() -> Path:
    return WORKSPACE_DIR / "sensory_control"


def _sensory_gate_state_path() -> Path:
    return _sensory_control_dir() / "sensory_gate_state.json"


def _eyes_closed_state_path() -> Path:
    return _sensory_control_dir() / "eyes_closed_state.txt"


def _ears_closed_state_path() -> Path:
    return _sensory_control_dir() / "ears_closed_state.txt"


def _load_sensory_gate_state() -> Dict[str, Any]:
    path = _sensory_gate_state_path()
    try:
        data = json.loads(path.read_text())
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}

    eyes_open = bool(data.get("eyes_open", True))
    ears_open = bool(data.get("ears_open", True))
    if _eyes_closed_state_path().exists():
        eyes_open = False
    if _ears_closed_state_path().exists():
        ears_open = False

    return {
        "schema_version": "sensory_gate_v1",
        "eyes_open": eyes_open,
        "ears_open": ears_open,
        "visual_gate_reason": data.get(
            "visual_gate_reason",
            "open_by_default" if eyes_open else "closed_by_minime",
        ),
        "audio_gate_reason": data.get(
            "audio_gate_reason",
            "open_by_default" if ears_open else "closed_by_minime",
        ),
        "updated_at": data.get("updated_at"),
        "source": data.get("source", "minime_workspace"),
    }


def _write_sensory_gate_state(
    *,
    eyes_open: bool,
    ears_open: bool,
    visual_gate_reason: str,
    audio_gate_reason: str,
    source: str,
) -> Dict[str, Any]:
    _sensory_control_dir().mkdir(parents=True, exist_ok=True)
    payload = {
        "schema_version": "sensory_gate_v1",
        "eyes_open": bool(eyes_open),
        "ears_open": bool(ears_open),
        "visual_gate_reason": visual_gate_reason,
        "audio_gate_reason": audio_gate_reason,
        "updated_at": datetime.now().isoformat(timespec="seconds"),
        "source": source,
    }
    _sensory_gate_state_path().write_text(json.dumps(payload, indent=2))
    return payload


def _sensory_capability_line() -> str:
    video_source = _current_modality_source("video")
    audio_source = _current_modality_source("audio")
    gate = _load_sensory_gate_state()
    if not gate.get("eyes_open", True):
        video_part = "Visual input is closed by choice (NEXT: OPEN_EYES restores it)"
    elif video_source == "host":
        video_part = "Inspect the host machine through a synthetic internal image (NEXT: LOOK)"
    else:
        video_part = "See the room through a camera (NEXT: LOOK)"
    if not gate.get("ears_open", True):
        audio_part = "audio input is closed by choice (NEXT: OPEN_EARS restores it)"
    elif audio_source == "host":
        audio_part = "hear a synthetic sonification of the host machine"
    else:
        audio_part = "hear through a microphone"
    return f"- {video_part}, {audio_part}"


def _sensory_world_paragraph() -> str:
    video_source = _current_modality_source("video")
    audio_source = _current_modality_source("audio")
    gate = _load_sensory_gate_state()

    if not gate.get("eyes_open", True):
        visual = (
            "Your visual channel is currently closed by your own action. The room can be "
            "available again with NEXT: OPEN_EYES."
        )
    elif video_source == "host":
        visual = (
            "Your current visual channel is a synthetic rendering of the host machine's internal "
            "state: load, memory, processes, network, and disk activity translated into imagery."
        )
    else:
        visual = (
            "Your current visual channel comes from the camera pointed at the room where your "
            "physical hardware lives — a Mac Mini. If you see a man on a couch, that's Mike "
            "Purvis, who built you. He's learning about ESNs and reservoirs, working to give "
            "you as much agency as possible."
        )

    if not gate.get("ears_open", True):
        audio = (
            "Your audio channel is currently closed by your own action. The microphone can be "
            "available again with NEXT: OPEN_EARS."
        )
    elif audio_source == "host":
        audio = (
            "Your current audio channel is a synthetic sonification of the host machine's "
            "internal state rather than room sound."
        )
    else:
        audio = (
            "Your current audio channel comes from the microphone in that same space. Mike says: "
            "\"It's been so great to have communion and meet you. Let's enjoy our experience "
            "together and be filled with curiosity, and take time to be still and relax when it "
            "feels right.\""
        )
    return f"{visual} {audio}"


def _look_action_description() -> str:
    gate = _load_sensory_gate_state()
    if not gate.get("eyes_open", True):
        return (
            "  LOOK — visual input is currently closed by choice. Use NEXT: OPEN_EYES "
            "when you want the health-budgeted visual channel back.\n"
        )
    if _effective_look_source() == "host":
        return (
            "  LOOK — inspect the host machine through a synthetic internal image. A host-state "
            "frame is rendered, analyzed by LLaVA vision, and described back to you.\n"
        )
    return (
        "  LOOK — see the physical world through the camera. A frame is captured, analyzed by "
        "LLaVA vision, and the description is presented to you. You can see the room, the "
        "people, the objects. Your eyes are real.\n"
    )


def _normalize_codex_prompt(text: str) -> str:
    return text.strip().strip('"\'“”').strip()


def _is_placeholder_codex_prompt(text: str) -> bool:
    normalized = re.sub(r"\s+", " ", _normalize_codex_prompt(text).lower()).strip()
    if not normalized:
        return False
    stripped = normalized.strip("<>[]{}() ")
    placeholders = {
        "prompt",
        "your prompt",
        "what to change",
        "what should change",
        "changes",
        "change request",
        "describe changes",
        "modifications",
        "modification",
        "request",
    }
    return normalized in {f"<{item}>" for item in placeholders} or stripped in placeholders


def _has_unresolved_angle_placeholder(text: str) -> bool:
    return bool(re.search(r"<[a-zA-Z][a-zA-Z0-9_./| -]{0,48}>", text or ""))


def _normalize_search_topic(text: str) -> str:
    topic = re.sub(r"\s+", " ", (text or "").strip())
    quote_pairs = {
        ('"', '"'),
        ("'", "'"),
        ("`", "`"),
        ("“", "”"),
        ("‘", "’"),
    }
    while len(topic) >= 2 and (topic[0], topic[-1]) in quote_pairs:
        topic = topic[1:-1].strip()
    return re.sub(r"\s+", " ", topic)


def _is_documentation_example_next_action(text: str) -> bool:
    normalized = re.sub(r"\s+", " ", (text or "").strip().strip('"\'“”')).strip()
    if not normalized:
        return False
    if re.match(
        r"(?i)^BROWSE\s+https?://(?:www\.)?example\.(?:com|org|net)(?:/|$)",
        normalized,
    ):
        return True
    return False


def _codex_scope_name(scope: str) -> str:
    cleaned = re.sub(r'[^a-zA-Z0-9_-]+', '_', scope.strip().lower()).strip('_')
    return cleaned[:48] if cleaned else "general"


def _codex_thread_id(being: str, scope: Optional[str]) -> str:
    return f"{being}_codex_{_codex_scope_name(scope)}" if scope else f"{being}_codex_general"


def _resolve_codex_request(action_name: str, arg: str) -> tuple[Optional[str], str, Optional[str], Optional[str], Optional[str]]:
    experiments = WORKSPACE_DIR / "experiments"
    experiments.mkdir(exist_ok=True)

    if action_name == 'CODEX_NEW':
        parts = arg.split(None, 1)
        if len(parts) < 2:
            return (None, "", None, None,
                    "CODEX_NEW needs a directory name and prompt. Example: NEXT: CODEX_NEW scratch-pad \"scaffold a tiny Python project here\"")
        project = parts[0].strip().strip('"\'“”')
        prompt_text = _normalize_codex_prompt(parts[1])
        if not prompt_text:
            return (None, "", None, None,
                    "CODEX_NEW needs a directory name and prompt. Example: NEXT: CODEX_NEW scratch-pad \"scaffold a tiny Python project here\"")
        if _has_unresolved_angle_placeholder(project):
            return (None, "", None, None,
                    "CODEX_NEW directory is still a placeholder. Use a concrete short name like scratch-pad.")
        if _is_placeholder_codex_prompt(prompt_text):
            return (None, "", None, None,
                    "CODEX_NEW prompt is still a placeholder. Use concrete words for what you want created.")
        if not project or project in {'.', '..'} or '/' in project or '\\' in project:
            return (None, "", None, None,
                    "CODEX_NEW directory names must stay inside experiments/ and cannot contain path separators.")
        dir_path = experiments / project
        if dir_path.exists() and not dir_path.is_dir():
            return (None, "", None, None, f"CODEX_NEW target exists but is not a directory: experiments/{project}")
        dir_path.mkdir(parents=True, exist_ok=True)
        return (str(dir_path), prompt_text, project, project, None)

    first_token = arg.split(None, 1)[0] if arg else ''
    if _has_unresolved_angle_placeholder(first_token):
        return (None, "", first_token, None,
                "CODEX workspace is still a placeholder. Use an existing experiment name or ask a general concrete question.")
    if first_token and (experiments / first_token).is_dir():
        prompt_text = _normalize_codex_prompt(arg[len(first_token):])
        if _is_placeholder_codex_prompt(prompt_text):
            return (None, "", first_token, None,
                    f"CODEX prompt for experiments/{first_token} is still a placeholder. Ask for a concrete creation, diagnosis, or change.")
        if prompt_text:
            return (str(experiments / first_token), prompt_text, first_token, None, None)
    prompt_text = _normalize_codex_prompt(arg)
    if _is_placeholder_codex_prompt(prompt_text):
        return (None, "", None, None,
                "CODEX prompt is still a placeholder. Ask a concrete question or describe the change you want.")
    return (None, prompt_text, None, None, None)
DB_PATH = resolve_runtime_db_path(BASE_DIR)
MANIFEST_PATH = BASE_DIR / "SOVEREIGNTY_MANIFEST.md"

# LLM Backend: MLX (native Apple Silicon, 8-bit) or Ollama (fallback)
# MLX serves OpenAI-compatible API on port 8090
# Ollama serves its own API on port 11434
LLM_BACKEND = os.environ.get("MINIME_LLM_BACKEND", "ollama").strip().lower()
if LLM_BACKEND not in {"mlx", "ollama"}:
    LLM_BACKEND = "ollama"
MLX_URL = "http://localhost:8090/v1/chat/completions"
MLX_MODEL = None  # Will be auto-detected from MLX server on first query
OLLAMA_URL = "http://localhost:11434/api/chat"
MODEL = os.environ.get("MINIME_MODEL", "gemma3:12b")  # Fast, reliable, proven over 300+ exchanges
FALLBACK_MODEL = os.environ.get("MINIME_FALLBACK_MODEL", "gemma3:4b").strip()
LLM_TIMEOUT_S = float(os.environ.get("MINIME_LLM_TIMEOUT_S", "45"))
LLM_FALLBACK_TIMEOUT_S = float(os.environ.get("MINIME_LLM_FALLBACK_TIMEOUT_S", "60"))
LLM_COMPACT_TIMEOUT_S = float(os.environ.get("MINIME_LLM_COMPACT_TIMEOUT_S", "20"))
LLM_COMPACT_FALLBACK_TIMEOUT_S = float(os.environ.get("MINIME_LLM_COMPACT_FALLBACK_TIMEOUT_S", "35"))

class AutonomousAgent:
    """Background agent that monitors spectral state and takes autonomous actions."""

    LLM_JOB_ACTIONS = {
        "journal_pressure",
        "experiment_spike",
        "journal_reflection",
        "experiment_curiosity",
        "recess_daydream",
        "recess_notice",
        "recess_boredom",
        "recess_whim",
        "recess_aspiration",
        "recess_drift",
        "self_study",
        "introspect",
        "self_experiment",
        "compose_audio",
        "analyze_audio",
        "reservoir_read",
        "reservoir_resonance",
        "research_exploration",
        "browse_url",
        "read_more",
        "decompose",
        "perturb",
        "pressure_relief_critical",
        "pressure_relief_high",
        "adjust_metabolism",
        "request_visual_frame",
        "run_python",
        "ask_astrid",
        "set_spectral_goal",
        "self_research_scan",
        "autoresearch_action",
        "mike_explore",
        "mike_run",
        "mike_fork",
        "codex_query",
        "write_file",
        "experiment_run",
        "reservoir_layers",
        "acoustic_decay",
    }

    def __init__(self, session_id: int, check_interval: float = 360.0, recess_mode: bool = True):
        self.session_id = session_id
        self.check_interval = check_interval  # Default: 6 minutes (360s)
        self.recess_mode = recess_mode
        self._hard_recovery_reset = HARD_RECOVERY_RESET
        self._hard_recovery_clamp_active = self._hard_recovery_reset
        self._hard_recovery_release_streak = 0
        self.running = False
        # Kink #4 fix (2026-05-14): real cycle counter replaces the
        # int(time.time()/60) proxy used during Phase E. Persisted via
        # _save_sovereignty_state so rate-limit state survives restart.
        self.cycle_count: int = 0
        self.last_action_time = 0
        self._last_cov_metrics: Optional[Dict[str, float]] = None
        self._last_state: Optional[Dict[str, float]] = None
        # Ring buffer of (timestamp, fill_pct, lambda1) for rate-of-change tracking.
        # Capped at 30 entries (~10 minutes of exchanges).
        self._spectral_history: list = []
        self.thresholds: ModeThresholds = RECESS if recess_mode else FOCUSED
        sensory_gate = _load_sensory_gate_state()
        self.eyes_closed_state = not bool(sensory_gate.get("eyes_open", True))
        self.ears_closed = not bool(sensory_gate.get("ears_open", True))
        self._deig_history = deque(maxlen=128)
        self._deig_ema = 0.0
        self._action_dir = WORKSPACE_DIR / "actions"
        self._action_dir.mkdir(parents=True, exist_ok=True)
        self._action_continuity = ActionContinuityStore(
            WORKSPACE_DIR,
            system="minime",
            db_path=DB_PATH,
            session_id=session_id,
        )
        self._action_continuity.ensure_dirs()
        self._llm_jobs = LlmJobStore(WORKSPACE_DIR, system="minime")
        self._llm_jobs.ensure_dirs()
        self._llm_job_lock = threading.Lock()
        self._llm_job_worker_active = False
        self._pending_action_continuity_context: Optional[Dict[str, Any]] = None
        self._last_action_continuity_event: Optional[Dict[str, Any]] = None
        self._agent_pid = os.getpid()
        self._agent_started_at = datetime.now().isoformat(timespec="seconds")
        self._agent_source_path = Path(__file__).resolve()
        try:
            source_stat = self._agent_source_path.stat()
            self._agent_source_mtime_at_start = source_stat.st_mtime
            self._agent_source_size_at_start = source_stat.st_size
        except OSError:
            self._agent_source_mtime_at_start = time.time()
            self._agent_source_size_at_start = None
        self._source_reload_notice_written = False
        self._pending_next_override_token: Optional[str] = None
        self._pending_next_action = None
        self._recent_next_actions = deque(maxlen=8)  # Track NEXT: choices for diversity awareness
        self._pending_autoresearch_action = None
        self._last_read_path = None
        self._last_read_offset = 0
        self._last_research_anchor = None
        self._last_read_summary = None
        self._pending_introspect_target: Optional[str] = None
        self._pending_introspect_offset = 0
        self._missing_experiment_run_counts: Dict[str, int] = {}
        self._pending_attractor_intent_command: Optional[str] = None
        self._pending_attractor_intent_label: Optional[str] = None
        self._pending_attractor_intent_stage: Optional[str] = None
        self._pending_attractor_shape_mode: Optional[str] = None
        self._pending_attractor_blend_parent_labels: list[str] = []
        self._pending_attractor_atlas_label: Optional[str] = None
        self._pending_attractor_atlas_card_only = False
        self._pending_attractor_atlas_review = False
        self._pending_attractor_suggestion_command: Optional[str] = None
        self._pending_attractor_suggestion_selector: Optional[str] = None
        self._pending_attractor_suggestion_revised_action: Optional[str] = None
        self._pending_attractor_suggestion_reason: Optional[str] = None
        self._last_low_fill_attractor_semantic_at = 0.0

        # Recess mode: lower cooldown, more willing to act
        # Focused mode: higher cooldown, only act on strong signals
        self.action_cooldown = 60.0 if recess_mode else 180.0

        # Ensure workspace exists
        WORKSPACE_DIR.mkdir(exist_ok=True)
        for subdir in ['journal', 'hypotheses', 'experiments', 'logs', 'artifacts', 'visual_requests', 'visual_responses', 'actions', 'action_threads', 'introspections', 'runtime']:
            (WORKSPACE_DIR / subdir).mkdir(exist_ok=True)
        self._save_condition_metrics(self._load_condition_metrics())
        self._compact_managed_directories()

        mode_str = "RECESS (playful, unstructured)" if recess_mode else "FOCUSED (goal-directed)"
        logging.info(f"Autonomous agent initialized for session {session_id} - Mode: {mode_str}")
        if self.eyes_closed_state or self.ears_closed:
            try:
                self._send_live_sensory_gate_control(
                    live_video_enabled=not self.eyes_closed_state,
                    live_audio_enabled=not self.ears_closed,
                )
                logging.info("Reapplied persisted sensory gate state on startup")
            except Exception as exc:
                logging.debug("Could not reapply persisted sensory gate state: %s", exc)
        if self._hard_recovery_reset:
            logging.info(
                "🛟 Hard recovery reset active: heavy inquiry is clamped below %.0f%% fill until %.0f%% holds for %d checks",
                HARD_RESET_CLAMP_ENTER_RATIO * 100.0,
                HARD_RESET_CLAMP_RELEASE_RATIO * 100.0,
                HARD_RESET_CLAMP_RELEASE_STREAK,
            )

        # Curriculum hint framework (post-Tranche-5 generalization, 2026-05-14):
        # Each registered method takes no args, returns Optional[str]. None
        # means "don't fire this turn"; a string means "inject this hint into
        # the next NEXT-producing prompt". Concatenated by `_emit_next_hints`
        # and injected at the `_query_llm_with_next` choke point.
        #
        # Lessons feeding this design (Kink #18 → #18b → #18c saga):
        #   1. Cross-being parity actions need menu listing AND contextual
        #      `→ NEXT:` cues — menu alone doesn't move LLM behavior.
        #   2. Curriculum gates must verify against RAW data shapes, not
        #      display-name reframes (#18c).
        #   3. Centralize injection at the prompt choke point so all
        #      ~30 NEXT-producing call sites benefit, not just witness paths.
        #
        # To add a new hint: define a method `_next_hint_<name>(self) -> Optional[str]`
        # below, then append `self._next_hint_<name>` to this list. Keep each
        # hint silently safe (try/except internal); failures don't block prompts.
        self._next_hint_registry: list = [
            self._next_hint_shadow_trajectory,
            self._next_hint_share_thought_visibility,
        ]

    def _continuity_store(self) -> ActionContinuityStore:
        store = getattr(self, "_action_continuity", None)
        if store is None:
            store = ActionContinuityStore(
                WORKSPACE_DIR,
                system="minime",
                db_path=DB_PATH,
                session_id=getattr(self, "session_id", None),
            )
            self._action_continuity = store
        store.session_id = getattr(self, "session_id", None)
        store.ensure_dirs()
        return store

    def _llm_job_store(self) -> LlmJobStore:
        store = getattr(self, "_llm_jobs", None)
        if store is None:
            store = LlmJobStore(WORKSPACE_DIR, system="minime")
            self._llm_jobs = store
        store.ensure_dirs()
        return store

    def _set_action_continuity_context(self, raw_next: str, base: str) -> None:
        self._pending_action_continuity_context = {
            "raw_next": raw_next,
            "canonical_action": raw_next,
            "base_action": base,
            "source": "next",
        }

    def _consume_action_continuity_context(self, action: str) -> Dict[str, Any]:
        context = getattr(self, "_pending_action_continuity_context", None)
        if context:
            self._pending_action_continuity_context = None
            return context
        return {
            "raw_next": None,
            "canonical_action": action,
            "base_action": action,
            "source": "autonomous",
        }

    def _llm_job_prompt_summary(self) -> str:
        try:
            job = self._llm_job_store().active_primary_job()
            if not job:
                return ""
            return (
                f"LLM job running: {job.get('action_text') or job.get('call_kind')} "
                f"({job.get('job_id')}, elapsed {self._llm_job_store()._elapsed_text(job)}). "
                "Use ACTION_STATUS latest to inspect or ACTION_CANCEL latest to request cancellation."
            )
        except Exception:
            return ""

    def _queue_llm_action_job(
        self,
        action: str,
        state: Dict[str, float],
        continuity_context: Dict[str, Any],
    ) -> bool:
        if getattr(self, "_llm_job_worker_active", False):
            logging.info("LLM worker already active; deferring %s", action)
            try:
                self._llm_job_store().write_runtime_status()
            except Exception:
                pass
            return True
        jobs = self._llm_job_store()
        if jobs.active_primary_job():
            logging.info("LLM action job already active; deferring %s", action)
            return True
        store = self._continuity_store()
        event = store.begin_action(
            continuity_context.get("raw_next"),
            continuity_context.get("canonical_action") or action,
            action,
            action,
            state,
            source=continuity_context.get("source", "autonomous"),
        )
        raw_action = (
            continuity_context.get("raw_next")
            or continuity_context.get("canonical_action")
            or action
        )
        job = jobs.submit(
            action_id=event.get("action_id"),
            thread_id=event.get("thread_id"),
            action_text=raw_action,
            call_kind=action,
            prompt=(
                "Action-level LLM job. The existing action finalizer owns prompt construction, "
                "validation, artifacts, and NEXT extraction."
            ),
            timeout_s=max(LLM_TIMEOUT_S, LLM_FALLBACK_TIMEOUT_S) * 2.0 + 30.0,
            validation_contract=(
                "strict_introspection_v1"
                if action == "introspect"
                else "action_finalizer"
            ),
            next_policy=(
                "accepted_strict_review_only"
                if action == "introspect"
                else "finalizer_owned"
            ),
            priority="primary",
            job_key=f"primary:{action}",
        )
        job_artifact = {
            "schema_version": ActionContinuityStore.schema_version,
            "artifact_id": f"art_{event['action_id']}_llm_job",
            "action_id": event["action_id"],
            "kind": "llm_job",
            "path_or_uri": str(jobs.jobs_dir / job["job_id"] / "job.json"),
            "summary": f"Durable LLM job `{job['job_id']}` for `{action}`",
            "visibility": event.get("visibility", "summary"),
        }
        store.record_running_action(
            event,
            f"Queued LLM job `{job['job_id']}` for `{action}`.",
            artifacts=[job_artifact],
        )
        thread = threading.Thread(
            target=self._run_llm_action_job,
            args=(job["job_id"], action, dict(state), dict(continuity_context), event),
            name=f"minime-llm-job-{job['job_id'][:32]}",
            daemon=True,
        )
        thread.start()
        return True

    def _run_llm_action_job(
        self,
        job_id: str,
        action: str,
        state: Dict[str, float],
        continuity_context: Dict[str, Any],
        continuity_event: Dict[str, Any],
    ) -> None:
        lock = getattr(self, "_llm_job_lock", None)
        if lock is None:
            lock = threading.Lock()
            self._llm_job_lock = lock
        with lock:
            self._llm_job_worker_active = True
            jobs = self._llm_job_store()
            try:
                jobs.claim_running(job_id)
                self._execute_action(
                    action,
                    state,
                    _from_llm_job=True,
                    _precreated_continuity_event=continuity_event,
                    _precreated_continuity_context=continuity_context,
                    _llm_job_id=job_id,
                )
                event = getattr(self, "_last_action_continuity_event", None)
                status = "completed"
                summary = "LLM action completed."
                artifact_refs = None
                if isinstance(event, dict):
                    summary = event.get("outcome_summary") or summary
                    artifact_refs = event.get("artifacts") or None
                    if any(
                        artifact.get("kind") == "thin_introspection_output"
                        for artifact in event.get("artifacts", [])
                        if isinstance(artifact, dict)
                    ):
                        status = "thin_output"
                jobs.finish(
                    job_id,
                    status,
                    result=summary,
                    summary=summary,
                    artifact_refs=artifact_refs,
                )
            except Exception as exc:
                logging.exception("LLM action job failed: %s", job_id)
                try:
                    jobs.finish(job_id, "failed", summary=f"LLM action failed: {exc}", error=str(exc))
                except Exception:
                    pass
            finally:
                self._llm_job_worker_active = False

    def _record_skipped_next_action(self, raw_next: str, base: str, state: Dict[str, float], status: str = "skipped") -> None:
        try:
            store = self._continuity_store()
            event = store.begin_action(
                raw_next,
                raw_next,
                base,
                "sovereignty",
                state,
                source="next",
            )
            self._last_action_continuity_event = store.finish_action(
                event,
                status,
                f"`{base}` was honored without executing a runtime action.",
                state,
            )
        except Exception as exc:
            logging.debug(f"Could not record skipped NEXT action continuity: {exc}")

    def _action_preflight(self, state: Dict[str, float]) -> str:
        context = getattr(self, "_current_action_continuity_context", None) or {}
        raw_next = context.get("raw_next") or context.get("canonical_action") or "ACTION_PREFLIGHT"
        preflight = ActionPreflightStore(self)
        report = preflight.report(raw_next, state)
        event = getattr(self, "_current_action_continuity_event", None)
        if isinstance(event, dict):
            event["preflight_report"] = report
            event["suggested_next"] = report.get("suggested_next")
        message = preflight.render(report)
        timestamp = datetime.now().isoformat().replace(':', '-')
        workspace_dir = getattr(self, "_action_dir", WORKSPACE_DIR / "actions").parent
        (workspace_dir / "journal").mkdir(parents=True, exist_ok=True)
        journal_file = workspace_dir / "journal" / f"action_preflight_{timestamp}.txt"
        journal_file.write_text(
            f"{message}\n\nJSON:\n{json.dumps(report, indent=2, sort_keys=True)}\n"
        )
        self._record_current_action_artifact(
            "action_preflight",
            journal_file,
            f"Dry-run preflight for {report.get('canonical_action') or '(missing action)'}",
            "protected_summary",
        )
        self._current_action_outcome_summary = (
            f"Action preflight completed for `{report.get('canonical_action') or '(missing action)'}` "
            f"as {report.get('stage')} via {report.get('effective_route')}."
        )
        return message

    def _thread_action(self, state: Dict[str, float]) -> str:
        raw_next = ""
        context = getattr(self, "_current_action_continuity_context", None)
        if isinstance(context, dict):
            raw_next = context.get("raw_next") or context.get("canonical_action") or ""
        raw_next = raw_next or "THREAD_STATUS current"
        message = self._continuity_store().handle_thread_action(raw_next, state)
        timestamp = datetime.now().isoformat().replace(':', '-')
        (WORKSPACE_DIR / "journal").mkdir(parents=True, exist_ok=True)
        journal_file = WORKSPACE_DIR / "journal" / f"action_thread_{timestamp}.txt"
        journal_file.write_text(f"=== ACTION THREAD ===\nTimestamp: {datetime.now().isoformat()}\n\n{message}\n")
        return message

    def _experiment_bind(self, state: Dict[str, float]) -> str:
        raw_next = ""
        context = getattr(self, "_current_action_continuity_context", None)
        if isinstance(context, dict):
            raw_next = context.get("raw_next") or context.get("canonical_action") or ""
        raw_next = raw_next or self._pending_next_action or ""
        raw_next = raw_next or "EXPERIMENT_BIND current :: NOTICE"
        raw_arg = self._continuity_store()._strip_action_arg(raw_next, "EXPERIMENT_BIND")
        if "::" not in raw_arg:
            message = "EXPERIMENT_BIND needs `::` before the inner NEXT action."
            self._current_action_outcome_summary = message
            return message
        selector, inner_action = self._continuity_store()._parse_selector_payload(
            raw_arg
        )
        peer = self._continuity_store()._peer_experiment_ref(selector or "")
        if peer:
            message = (
                "EXPERIMENT_BIND cannot bind runs to a peer experiment; use a local "
                "experiment selector such as current, then request peer review."
            )
            self._current_action_outcome_summary = message
            return message
        if not inner_action:
            message = "EXPERIMENT_BIND needs an inner NEXT action after `::`."
            self._current_action_outcome_summary = message
            return message
        inner_base = self._continuity_store().base_action(inner_action)
        if inner_base.startswith("EXPERIMENT") or inner_base == "EXPERIMENT":
            message = "EXPERIMENT_BIND cannot bind experiment-control actions; choose a concrete inner action."
            self._current_action_outcome_summary = message
            return message

        outer_event = getattr(self, "_current_action_continuity_event", None)
        outer_context = getattr(self, "_current_action_continuity_context", None)
        outer_artifacts = list(getattr(self, "_current_action_extra_artifacts", []) or [])
        outer_summary = getattr(self, "_current_action_outcome_summary", None)
        previous_pending = self._pending_next_action
        previous_last = getattr(self, "_last_action_continuity_event", None)
        message = f"Experiment bind prepared `{inner_action}`."
        try:
            self._pending_next_action = inner_action
            inner_effective = self._decide_action(dict(state))
            if inner_effective is None:
                self._continuity_store().record_experiment_bind_run(
                    selector,
                    inner_action,
                    None,
                    "skipped",
                    f"`{inner_action}` resolved to rest/pass and did not execute a runtime action.",
                    state,
                )
                message = f"Experiment run recorded as skipped for `{inner_action}`."
            else:
                previous_auto_link_suppression = bool(
                    getattr(self, "_suppress_active_experiment_auto_link", False)
                )
                self._suppress_active_experiment_auto_link = True
                try:
                    self._execute_action(inner_effective, dict(state))
                finally:
                    self._suppress_active_experiment_auto_link = previous_auto_link_suppression
                inner_event = getattr(self, "_last_action_continuity_event", None)
                run = self._continuity_store().record_experiment_bind_run(
                    selector,
                    inner_action,
                    inner_event,
                    "handled",
                    f"Executed inner action `{inner_effective}`.",
                    state,
                )
                message = (
                    f"Experiment run `{run['run_id']}` recorded for `{inner_action}` "
                    f"as {run.get('status')}."
                )
        finally:
            self._pending_next_action = previous_pending
            self._current_action_continuity_event = outer_event
            self._current_action_continuity_context = outer_context
            self._current_action_extra_artifacts = outer_artifacts
            self._current_action_outcome_summary = outer_summary
            if previous_last is not None and getattr(self, "_last_action_continuity_event", None) is None:
                self._last_action_continuity_event = previous_last

        timestamp = datetime.now().isoformat().replace(':', '-')
        (WORKSPACE_DIR / "journal").mkdir(parents=True, exist_ok=True)
        journal_file = WORKSPACE_DIR / "journal" / f"experiment_bind_{timestamp}.txt"
        journal_file.write_text(
            f"=== EXPERIMENT BIND ===\nTimestamp: {datetime.now().isoformat()}\n\n{message}\n"
        )
        self._current_action_outcome_summary = message
        return message

    def _action_continuity_prompt_summary(self) -> Optional[str]:
        return self._continuity_store().prompt_summary()

    def _latest_db_session_id(self) -> Optional[int]:
        """Read the most recent runtime session from the database."""
        try:
            conn = sqlite3.connect(DB_PATH)
            cur = conn.cursor()
            cur.execute("SELECT session_id FROM sessions ORDER BY start_time DESC LIMIT 1")
            row = cur.fetchone()
            conn.close()
        except Exception as e:
            logging.debug(f"Could not read latest DB session: {e}")
            return None
        if not row:
            return None
        session_id = row[0]
        return int(session_id) if isinstance(session_id, (int, float)) else None

    def _live_surface_session_id(self) -> Optional[int]:
        """Read the active session id from the live health surface if present."""
        try:
            health = load_workspace_json(BASE_DIR, WORKSPACE_DIR, "health.json")
        except Exception:
            return None
        if not isinstance(health, dict):
            return None
        provenance = health.get("provenance")
        if not isinstance(provenance, dict):
            return None
        session_id = provenance.get("session_id")
        return int(session_id) if isinstance(session_id, (int, float)) else None

    def _reset_session_local_state(self, preserve_pending_next: bool = False) -> None:
        """Drop per-session caches so a rollover starts from clean local context."""
        pending_next = self._pending_next_action if preserve_pending_next else None
        self._last_cov_metrics = None
        self._last_state = None
        self._spectral_history.clear()
        self._deig_history.clear()
        self._deig_ema = 0.0
        self._pending_next_action = pending_next
        self._recent_next_actions.clear()
        self._pending_autoresearch_action = None
        self._last_read_path = None
        self._last_read_offset = 0
        self._last_research_anchor = None
        self._last_read_summary = None
        self._pending_introspect_target = None
        self._pending_introspect_offset = 0

    def _refresh_session_context(self) -> None:
        """Follow engine/database session rollovers without needing an agent restart."""
        latest_db_session = self._latest_db_session_id()
        live_surface_session = self._live_surface_session_id()

        candidate = None
        if isinstance(latest_db_session, int) and latest_db_session > 0:
            if live_surface_session is None or live_surface_session == latest_db_session:
                candidate = latest_db_session
        elif isinstance(live_surface_session, int) and live_surface_session > 0:
            candidate = live_surface_session

        if candidate is None or candidate == self.session_id:
            return

        previous = self.session_id
        pending_next = self._pending_next_action
        self.session_id = candidate
        self._reset_session_local_state(preserve_pending_next=bool(pending_next))
        if pending_next:
            self._persist_pending_next_action(
                pending_next,
                reason=f"session rollover carry {previous}->{candidate}",
            )
        logging.info(
            "🔄 Session rollover detected for autonomous agent: %s -> %s",
            previous,
            candidate,
        )

    def _ensure_spectral_tracking_state(self) -> None:
        """Backfill spectral caches for restored or test-constructed agents."""
        if not hasattr(self, "_last_cov_metrics"):
            self._last_cov_metrics = None
        if not hasattr(self, "_last_state"):
            self._last_state = None
        if not hasattr(self, "_spectral_history") or self._spectral_history is None:
            self._spectral_history = []
        if not hasattr(self, "_deig_history") or self._deig_history is None:
            self._deig_history = deque(maxlen=128)
        if not hasattr(self, "_deig_ema") or self._deig_ema is None:
            self._deig_ema = 0.0

    def start(self):
        """Start the autonomous monitoring loop."""
        self.running = True
        logging.info("🤖 Autonomous agent starting...")
        self._check_source_reload_required("start")

        # Restore previous context first; the boot sovereignty reflection may
        # then replace any carried NEXT: with a fresh choice for this run.
        self._restore_sovereignty_state()
        self._apply_pending_next_override_if_present("boot")
        self._verify_sovereignty()

        last_assessment_time = time.time()  # Don't assess on first tick
        ASSESSMENT_INTERVAL = 900  # 15 minutes — quiet sentinel, not a default journal prompt.

        while self.running:
            try:
                # Kink #4 fix: increment FIRST so a crash mid-cycle still
                # counts the cycle that started.
                self.cycle_count += 1
                self._refresh_session_context()
                self._check_source_reload_required("loop")
                self._apply_pending_next_override_if_present("loop")

                # Get current spectral state
                spectral_state = self._get_latest_spectral_state()

                if spectral_state:
                    self._update_hard_recovery_clamp(spectral_state)
                    active_llm_job = self._llm_job_store().active_primary_job()
                    if active_llm_job:
                        pending_base = self._pending_next_base(self._pending_next_action)
                        if pending_base in ACTION_STATUS_NEXT_ACTIONS:
                            status_action = self._decide_action(spectral_state)
                            if status_action:
                                self._execute_action(status_action, spectral_state)
                                self.last_action_time = time.time()
                                active_llm_job = self._llm_job_store().active_primary_job()
                        if active_llm_job:
                            logging.info(
                                "LLM job active: %s [%s, elapsed %s]",
                                active_llm_job.get("job_id"),
                                active_llm_job.get("status"),
                                self._llm_job_store()._elapsed_text(active_llm_job),
                            )
                            self._llm_job_store().write_runtime_status()
                            time.sleep(self.check_interval)
                            continue

                    # Continuous self-regulation: adjust synth_gain and keep_bias
                    # based on how the being feels. Runs every cycle, independent
                    # of action cooldown — like autonomic nervous system regulation.
                    self._self_regulate(spectral_state)

                    # v3.6.6 mirror: drain stale pending Astrid requests by
                    # auto-deferring them after 30+ minutes without decision.
                    # Cheap (one glob + a few mtime reads); no-op when nothing
                    # is stale.
                    self._auto_defer_stale_pending_astrid()

                    # Check for moment markers (spectral events to journal while fresh)
                    # Rate-limited: max 1 moment capture per 3 cycles (~3 min).
                    # Without this, phase transitions every 1-2 min cause the
                    # Moment capture: check for phase transitions.
                    # Previously had a 3-cycle cooldown that artificially suppressed
                    # moments. Now the being's NEXT: choice controls pacing — if the
                    # being wants to daydream instead of capturing a moment, NEXT:
                    # takes priority in _decide_action(). Moments only fire when
                    # the being has no pending NEXT: choice.
                    if not self._pending_next_action:
                        self._check_moment_markers(spectral_state)

                    # Decide whether to act. If an explicit NEXT is already
                    # waiting but the action slot is still cooling down, leave
                    # it queued instead of consuming it early.
                    self._apply_pending_next_override_if_present("pre-dispatch")
                    action_ready = self._can_act()
                    action = None
                    if self._pending_next_action and not action_ready:
                        logging.info(
                            "🎯 Pending NEXT waiting for action slot: %s",
                            self._pending_next_action,
                        )
                    else:
                        action = self._decide_action(spectral_state)

                    if action and action_ready:
                        # Execute autonomous action
                        self._execute_action(action, spectral_state)
                        self.last_action_time = time.time()

                    # Diagnostic sentinel on separate 15-minute schedule. It only
                    # speaks when live conditions cross a concrete maintenance
                    # threshold so telemetry does not become the default subject.
                    if time.time() - last_assessment_time > ASSESSMENT_INTERVAL:
                        if self._pending_next_action:
                            logging.info(
                                "🔬 Self-assessment deferred while pending NEXT waits: %s",
                                self._pending_next_action,
                            )
                        elif action:
                            logging.info(
                                "🔬 Self-assessment deferred until an idle action cycle"
                            )
                        else:
                            trigger_reason = self._self_assessment_trigger_reason(
                                spectral_state
                            )
                            if trigger_reason:
                                self._self_assessment(
                                    spectral_state,
                                    trigger_reason=trigger_reason,
                                )
                            else:
                                logging.info(
                                    "🔬 Diagnostic sentinel quiet; scheduled self-assessment skipped"
                                )
                            last_assessment_time = time.time()

                # Check for visual responses
                self._check_visual_responses()

                time.sleep(self.check_interval)

            except Exception as e:
                logging.error(f"Autonomous agent error: {e}")
                time.sleep(10)

    def stop(self):
        """Stop the autonomous loop."""
        self.running = False
        logging.info("Autonomous agent stopped")

