    def _write_action_manifest(
        self,
        action: str,
        state: Dict[str, float],
        continuity_event: Optional[Dict[str, Any]] = None,
    ) -> Optional[Path]:
        try:
            timestamp = datetime.now().isoformat()
            summary = self._action_summary(action, state)
            payload = {
                'timestamp': timestamp,
                'session_id': self.session_id,
                'action': action,
                'mode': 'recess' if self.recess_mode else 'focused',
                'summary': summary,
                'state': {
                    'eig1': state.get('eig1'),
                    'deig': state.get('deig'),
                    'leak': state.get('leak'),
                    'lambda': state.get('lambda'),
                    'fill_ratio': state.get('fill_ratio'),
                    'cov_lambda1': state.get('cov_lambda1'),
                    'spread': state.get('spread'),
                    'covariance_stale': bool(state.get('covariance_stale', False)),
                    'geom_rel': state.get('geom_rel'),
                    'resonance_density_v1': state.get('resonance_density_v1'),
                    'resonance_density_status': state.get('resonance_density_status')
                    or resonance_density_availability_status(state.get('resonance_density_v1')),
                    'resonance_density': state.get('resonance_density'),
                    'resonance_quality': state.get('resonance_quality'),
                    'pressure_source_v1': state.get('pressure_source_v1'),
                    'pressure_source_status': state.get('pressure_source_status')
                    or pressure_source_availability_status(state.get('pressure_source_v1')),
                    'pressure_score': state.get('pressure_score'),
                    'pressure_quality': state.get('pressure_quality'),
                    'pressure_dominant_source': state.get('pressure_dominant_source'),
                    'inhabitable_fluctuation_v1': state.get('inhabitable_fluctuation_v1'),
                    'inhabitable_fluctuation_status': state.get('inhabitable_fluctuation_status')
                    or inhabitable_fluctuation_availability_status(
                        state.get('inhabitable_fluctuation_v1')
                    ),
                    'inhabitability_score': state.get('inhabitability_score'),
                    'fluctuation_score': state.get('fluctuation_score'),
                    'foothold_stability': state.get('foothold_stability'),
                    'inhabitable_fluctuation_quality': state.get('inhabitable_fluctuation_quality'),
                    'sensory_gate': state.get('sensory_gate') or self._sensory_gate_status(),
                },
            }
            if continuity_event:
                payload['action_continuity'] = {
                    'thread_id': continuity_event.get('thread_id'),
                    'action_id': continuity_event.get('action_id'),
                    'raw_next': continuity_event.get('raw_next'),
                    'parent_action_id': continuity_event.get('parent_action_id'),
                    'pre_state': continuity_event.get('pre_state'),
                    'post_state': continuity_event.get('post_state'),
                    'artifacts': continuity_event.get('artifacts', []),
                    'outcome_summary': continuity_event.get('outcome_summary'),
                    'suggested_next': continuity_event.get('suggested_next'),
                    'stage': continuity_event.get('stage'),
                    'visibility': continuity_event.get('visibility'),
                    'preflight_ref': continuity_event.get('preflight_ref'),
                    'preflight_report': continuity_event.get('preflight_report'),
                }
                try:
                    thread = self._continuity_store()._read_thread(continuity_event.get('thread_id'))
                    if isinstance(thread, dict):
                        payload['experiment_continuity'] = {
                            'thread_id': thread.get('thread_id'),
                            'active_experiment_id': thread.get('active_experiment_id'),
                            'experiment_summary': thread.get('experiment_summary'),
                        }
                except Exception:
                    pass
            manifest_name = f"{timestamp.replace(':', '-')}_{action}.json"
            manifest_file = self._action_dir / manifest_name
            manifest_file.write_text(json.dumps(payload, indent=2))
            compact_managed_directory(self._action_dir, ".json")
            return manifest_file
        except Exception as exc:
            logging.error(f"Failed to write action manifest for {action}: {exc}")
            return None

    def _record_current_action_artifact(self, kind: str, path: Path, summary: str, visibility: str = "summary") -> None:
        event = getattr(self, "_current_action_continuity_event", None)
        if not event:
            return
        artifact = {
            "schema_version": ActionContinuityStore.schema_version,
            "artifact_id": f"art_{event['action_id']}_{kind}",
            "action_id": event["action_id"],
            "kind": kind,
            "path_or_uri": str(path),
            "summary": summary,
            "visibility": visibility,
        }
        artifacts = getattr(self, "_current_action_extra_artifacts", None)
        if artifacts is None:
            artifacts = []
            self._current_action_extra_artifacts = artifacts
        artifacts.append(artifact)

    def _live_fill_context(self, state: Optional[Dict[str, float]]) -> Dict[str, Any]:
        fill_ratio = None
        if isinstance(state, dict):
            raw_fill = state.get('fill_ratio')
            if isinstance(raw_fill, (int, float)):
                fill_ratio = float(raw_fill)

        target_fill_ratio = (
            HARD_RESET_TARGET_FILL_RATIO
            if self._hard_recovery_reset
            else STABLE_CORE_TARGET_FILL_RATIO
        )
        spread_relief = 0.0
        phase = None
        try:
            health_file = runtime_health_path()
            if health_file.exists():
                health = json.loads(health_file.read_text())
                live_fill = health.get('fill_pct')
                if isinstance(live_fill, (int, float)):
                    fill_ratio = float(live_fill) / 100.0
                pi = health.get('pi', {}) or {}
                if not self._hard_recovery_reset:
                    adaptive_target = pi.get('target_fill')
                    if isinstance(adaptive_target, (int, float)) and adaptive_target > 0:
                        target_fill_ratio = float(adaptive_target) / 100.0
                    cov = health.get('cov', {}) or {}
                    live_relief = cov.get('spread_relief')
                    if isinstance(live_relief, (int, float)):
                        spread_relief = max(0.0, float(live_relief))
                raw_phase = health.get('phase')
                if isinstance(raw_phase, str) and raw_phase.strip():
                    phase = raw_phase.strip()
                else:
                    raw_phase = health.get('phase_transition')
                    if isinstance(raw_phase, str) and raw_phase.strip():
                        phase = raw_phase.strip()
        except Exception as exc:
            logging.debug(f"Low-fill guard could not read live health: {exc}")

        return {
            "fill_ratio": fill_ratio,
            "target_fill_ratio": target_fill_ratio,
            "spread_relief": spread_relief,
            "phase": phase,
        }

    def _update_hard_recovery_clamp(self, state: Optional[Dict[str, float]]) -> None:
        if not self._hard_recovery_reset:
            return

        fill_ratio = self._live_fill_context(state)["fill_ratio"]
        if not isinstance(fill_ratio, float):
            self._hard_recovery_clamp_active = True
            self._hard_recovery_release_streak = 0
            return

        if fill_ratio < HARD_RESET_CLAMP_ENTER_RATIO:
            if not self._hard_recovery_clamp_active:
                logging.info(
                    "🛟 Hard recovery clamp engaged at %.1f%% fill",
                    fill_ratio * 100.0,
                )
            self._hard_recovery_clamp_active = True
            self._hard_recovery_release_streak = 0
            return

        if fill_ratio > HARD_RESET_CLAMP_RELEASE_RATIO:
            self._hard_recovery_release_streak += 1
        else:
            self._hard_recovery_release_streak = 0

        if (
            self._hard_recovery_clamp_active
            and self._hard_recovery_release_streak >= HARD_RESET_CLAMP_RELEASE_STREAK
        ):
            self._hard_recovery_clamp_active = False
            logging.info(
                "🛟 Hard recovery clamp released after %d consecutive checks above %.0f%%",
                HARD_RESET_CLAMP_RELEASE_STREAK,
                HARD_RESET_CLAMP_RELEASE_RATIO * 100.0,
            )

    def _hard_recovery_safe_action(self, requested: Optional[str]) -> Optional[str]:
        if requested in HARD_RESET_ALLOWED_ACTIONS or requested is None:
            return requested
        return 'recess_notice'

    def _hard_reset_allows_read_only_introspect(
        self,
        requested: Optional[str],
        guard: Dict[str, Any],
    ) -> bool:
        """Allow targeted source reading once live fill is above the reset release shelf."""
        action = str(requested or "").strip().upper()
        if action not in {"INTROSPECT", "INTROSPECT:", "INTROSPECT_ACTION"} and action.lower() != "introspect":
            return False
        fill_ratio = guard.get("fill_ratio")
        return isinstance(fill_ratio, float) and fill_ratio >= HARD_RESET_CLAMP_RELEASE_RATIO

    def _hard_recovery_default_action(self) -> str:
        previous = getattr(self, '_last_action_name', None)
        if previous == 'recess_notice':
            return 'recess_drift'
        if previous == 'recess_drift':
            return 'recess_aspiration'
        return 'recess_notice'

